//! Gate A — implementation parity vs the server's OWN ONNX graph run in Python
//! onnxruntime (`golden_ort/`, generated by scripts/make_golden.py).
//!
//! Runs for BOTH backends (native CT4 forward and ONNX Runtime): each must
//! match the golden within mean cos ≥ 0.9999, max |Δ| < 1e-3 (in practice
//! native ≈ 1e-6, ORT ≈ 1e-7). Proves the wrapper math is bug-free: Qwen BPE
//! used verbatim with add_special_tokens=false, empty-string pad fallback,
//! int32 input wiring (ORT), exact mask discipline (native). A breach fails
//! the build.
//!
//! Requires (generated by scripts/make_golden.py):
//!   - $CARGO_MANIFEST_DIR/golden_ort/{queries.json,vectors.npy}
//!   - model dir (defaults to ./model, built by scripts/build_model_dir.py)
//! Skips (with a printed notice) if absent, so a plain `cargo test` on a fresh
//! checkout doesn't hard-fail before goldens exist.

use std::path::{Path, PathBuf};

use custom_names_embeddings_server::engine::Engine;

const MEAN_COS_MIN: f32 = 0.9999;
const MAX_ABS_DIFF: f32 = 1e-3;

/// Minimal NumPy `.npy` reader for a C-order `<f4` 2-D array (what `np.save`
/// writes for a float32 matrix). Returns (rows, cols, flat row-major data).
fn read_npy_f32(path: &Path) -> (usize, usize, Vec<f32>) {
    let bytes = std::fs::read(path).expect("read npy");
    assert_eq!(&bytes[0..6], b"\x93NUMPY", "not a npy file");
    let major = bytes[6];
    let (hdr_len, data_start) = if major == 1 {
        (u16::from_le_bytes([bytes[8], bytes[9]]) as usize, 10)
    } else {
        (u32::from_le_bytes([bytes[8], bytes[9], bytes[10], bytes[11]]) as usize, 12)
    };
    let header = std::str::from_utf8(&bytes[data_start..data_start + hdr_len]).expect("hdr utf8");
    assert!(header.contains("'<f4'") || header.contains("\"<f4\""), "expected <f4, got {header}");
    assert!(header.contains("False"), "expected C-order (fortran_order False): {header}");
    let shp = header.split("'shape':").nth(1).expect("shape key");
    let inside = &shp[shp.find('(').unwrap() + 1..shp.find(')').unwrap()];
    let dims: Vec<usize> = inside
        .split(',')
        .filter_map(|s| s.trim().parse().ok())
        .collect();
    let (rows, cols) = (dims[0], dims[1]);
    let off = data_start + hdr_len;
    let raw = &bytes[off..];
    assert_eq!(raw.len(), rows * cols * 4, "npy data size mismatch");
    let mut data = vec![0f32; rows * cols];
    for (i, c) in raw.chunks_exact(4).enumerate() {
        data[i] = f32::from_le_bytes([c[0], c[1], c[2], c[3]]);
    }
    (rows, cols, data)
}

fn manifest() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

fn model_dir() -> PathBuf {
    std::env::var("CT4_MODEL_DIR")
        .map(PathBuf::from)
        .unwrap_or_else(|_| manifest().join("model")) // built by scripts/build_model_dir.py
}

fn ort_intra_default() -> usize {
    std::env::var("CT4_ORT_INTRA_THREADS").ok().and_then(|s| s.parse().ok()).unwrap_or(8)
}

/// Embed `names` with the given engine, chunked in input order (no
/// length-sorting, to keep row alignment with the golden).
fn embed_ordered(engine: &Engine, names: &[String]) -> Vec<Vec<f32>> {
    let mut out = Vec::with_capacity(names.len());
    for chunk in names.chunks(64) {
        let ids = engine.tokenizer().encode_ids(chunk).expect("encode");
        let (vecs, _t) = engine.infer_ids(&ids).expect("infer");
        out.extend(vecs);
    }
    out
}

fn check_against_golden(engine_name: &str, server_vecs: &[Vec<f32>], cols: usize, golden: &[f32], names: &[String]) {
    let mut cos_sum = 0.0f64;
    let mut cos_min = 1.0f32;
    let mut max_abs = 0.0f32;
    let mut worst_idx = 0usize;
    for (i, sv) in server_vecs.iter().enumerate() {
        let gv = &golden[i * cols..(i + 1) * cols];
        let mut dot = 0.0f32;
        for (a, b) in sv.iter().zip(gv.iter()) {
            dot += a * b;
            max_abs = max_abs.max((a - b).abs());
        }
        if dot < cos_min {
            cos_min = dot;
            worst_idx = i;
        }
        cos_sum += dot as f64;
    }
    let mean_cos = (cos_sum / server_vecs.len() as f64) as f32;
    println!(
        "Gate A [{engine_name}]: N={} dim={} mean_cos={:.6} min_cos={:.6} (worst idx {} = {:?}) max_abs_diff={:.2e}",
        server_vecs.len(),
        cols,
        mean_cos,
        cos_min,
        worst_idx,
        names.get(worst_idx).map(|s| s.chars().take(30).collect::<String>()),
        max_abs
    );
    assert!(mean_cos >= MEAN_COS_MIN, "[{engine_name}] mean cosine {mean_cos:.6} < {MEAN_COS_MIN}");
    assert!(max_abs < MAX_ABS_DIFF, "[{engine_name}] max abs diff {max_abs:.2e} >= {MAX_ABS_DIFF:.0e}");
}

#[test]
fn gate_a_parity_vs_golden_ort() {
    let golden_dir = manifest().join("golden_ort");
    let q = golden_dir.join("queries.json");
    let v = golden_dir.join("vectors.npy");
    let md = model_dir();
    if !q.exists() || !v.exists() {
        eprintln!(
            "SKIP gate_a: missing golden_ort.\n  expected {q:?}, {v:?}\n  generate with: python scripts/make_golden.py --out golden_ort"
        );
        return;
    }

    let names: Vec<String> =
        serde_json::from_str(&std::fs::read_to_string(&q).unwrap()).expect("queries.json");
    let (rows, cols, golden) = read_npy_f32(&v);
    assert_eq!(rows, names.len(), "golden rows vs names mismatch");

    // Native backend (weights.bin + manifest).
    if md.join("weights.bin").exists() {
        let engine = Engine::load_native(&md, &md.join("tokenizer.json"), 64).expect("native engine load");
        assert_eq!(engine.dim(), cols, "native dim != golden dim");
        let vecs = embed_ordered(&engine, &names);
        check_against_golden("native", &vecs, cols, &golden, &names);
    } else {
        eprintln!("SKIP gate_a [native]: no {}/weights.bin", md.display());
    }

    // ORT backend (reference).
    if md.join("model.onnx").exists() {
        let engine = Engine::load_ort(
            &md.join("model.onnx"),
            &md.join("tokenizer.json"),
            ort_intra_default(),
            1,
            64,
        )
        .expect("ort engine load");
        assert_eq!(engine.dim(), cols, "ort dim != golden dim");
        let vecs = embed_ordered(&engine, &names);
        check_against_golden("ort", &vecs, cols, &golden, &names);
    } else {
        eprintln!("SKIP gate_a [ort]: no {}/model.onnx", md.display());
    }
}
